using UrlShortener.Core.Links;

namespace UrlShortener.Infrastructure.Persistence;

public sealed class ShortenerDbContext(DbContextOptions<ShortenerDbContext> options) : DbContext(options)
{
    public DbSet<Link> Links => Set<Link>();

    public DbSet<Click> Clicks => Set<Click>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        var link = modelBuilder.Entity<Link>();
        link.ToTable("links");
        link.HasKey(l => l.Id);
        link.Property(l => l.Code).HasMaxLength(LinkValidator.MaxAliasLength).IsRequired();
        link.HasIndex(l => l.Code).IsUnique();
        link.Property(l => l.LongUrl).HasMaxLength(LinkValidator.MaxUrlLength).IsRequired();
        link.Property(l => l.CreatedAt).IsRequired();
        link.Property(l => l.ClickCount).IsRequired();

        var click = modelBuilder.Entity<Click>();
        click.ToTable("clicks");
        click.HasKey(c => c.Id);
        click.Property(c => c.OccurredAt).IsRequired();
        click.Property(c => c.Referrer).HasMaxLength(Click.MaxReferrerLength);
        click.Property(c => c.UserAgent).HasMaxLength(Click.MaxUserAgentLength);
        click.HasOne<Link>().WithMany().HasForeignKey(c => c.LinkId).OnDelete(DeleteBehavior.Cascade);
        click.HasIndex(c => new { c.LinkId, c.Id });
    }
}
